while True:
    msg = inbound.pop()                 # SPSC ring, already parsed
    if msg.kind == "FILL":
        positions.on_fill(msg)          # idempotent: dedupe on exec ID
    elif msg.kind == "TICK":
        quote = strategy.decide(msg, positions)
        if quote and risk.check(quote): # synchronous gate, before send
            outbound.send(encode(quote))
